function fmt(v){ return Math.round(v*10)/10; }
function transformCss(t){
  t=t||{};
  var tx=+t.tx||0, ty=+t.ty||0, rot=+t.rot||0;
  var sx=+t.sx, gx=isNaN(sx)?1:sx, sy=+t.sy, gy=isNaN(sy)?1:sy, skx=+t.skx||0, sky=+t.sky||0;
  var p=[];
  if(tx||ty) p.push('translate('+fmt(tx)+'px, '+fmt(ty)+'px)');
  if(rot) p.push('rotate('+fmt(rot)+'deg)');
  if(gx!==1||gy!==1) p.push('scale('+fmt(gx)+', '+fmt(gy)+')');
  if(skx||sky) p.push('skew('+fmt(skx)+'deg, '+fmt(sky)+'deg)');
  var v=p.join(' ')||'none';
  return {css:'transform: '+v+';', value:v};
}
var EXPORTS={transformCss:transformCss};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TransformForgePure = EXPORTS; }
